-- 팩토리를 만든다

@SpringBootTest
@Transactional
class FirstQueryTest {

    @PersistenceContext EntityManager em;
    JPAQueryFactory queryFactory;

    @BeforeEach
    void init() {
        queryFactory = new JPAQueryFactory(em);

        Team teamA = new Team("teamA");
        em.persist(teamA);
        em.persist(new Member("m1", 10, teamA));
        em.persist(new Member("m2", 20, teamA));
        em.flush();
        em.clear();
    }
}

--   EntityManager 하나를 넘긴다


-- 한 줄을 조립한다

@Test
void 첫_쿼리() {
    Member found = queryFactory
            .selectFrom(member)
            .where(member.username.eq("m1"))
            .fetchOne();

    System.out.println("이름: " + found.getUsername());
    System.out.println("나이: " + found.getAge());
}

