-- 조립과 실행을 나눠 본다

@Test
void 나눠서() {
    System.out.println("--- 조립 시작 ---");
    JPAQuery<Member> query = queryFactory
            .selectFrom(member)
            .where(member.age.goe(15));
    System.out.println("--- 조립 끝 ---");
    System.out.println("JPQL: " + query);
    System.out.println("--- fetch ---");
    List<Member> result = query.fetch();
    System.out.println("건수: " + result.size());
}

